uint32_t final_avalanche(uint32_t x) {
    x ^= x &gt;&gt; 16;
    x *= 0x85EBCA6B;
    x ^= x &gt;&gt; 13;
    x *= 0xC2B2AE35;
    x ^= x &gt;&gt; 16;
    return x;
